    public function index(Request $request)
    {
        $perPage = Input::page($request);
        $request->validate(['scope' => 'sometimes|in:global,client,site', 'client_id' => 'sometimes|integer|min:1', 'is_active' => 'sometimes|boolean', 'search' => 'sometimes|string|max:255']);
        $query = NextcloudConnection::query()->orderBy('id');
