    public function context(Request $request, ?NextcloudConnection $connection = null)
    {
        $perPage = Input::page($request);
        $kind = $request->input('kind', 'clients');
        $request->validate(['kind' => 'sometimes|in:clients,sites,contacts,users,roles,calendars']);
        $clientId = $connection && $connection->scope !== 'global' ? $connection->client_id : null;
        $query = match ($kind) {
            'clients' => Client::query()->when($clientId, fn ($q) => $q->whereKey($clientId))->select('id', 'name'),
            'sites' => ClientSite::query()->when($clientId, fn ($q) => $q->where('client_id', $clientId))->select('id', 'client_id', 'name'),
            'contacts' => ClientUser::query()->where('active', true)->when($clientId, fn ($q) => $q->whereHas('site', fn ($s) => $s->where('client_id', $clientId)))->select('id', 'client_site_id', 'name', 'email', 'role'),
            'users' => User::query()->where('status', User::STATUS_ACTIVE)->when($clientId, fn ($q) => $q->whereRaw('1 = 0'))->select('id', 'name', 'email'),
            'roles' => Role::query()->when($clientId, fn ($q) => $q->whereRaw('1 = 0'))->select('id', 'name'),
            'calendars' => Calendar::query()->when($clientId, fn ($q) => $q->whereRaw('1 = 0'))->select('id', 'name', 'type', 'owner_type', 'owner_id'),
        };
        $data = $query->orderBy('id')->paginate($perPage)->through(fn ($row) => $row->getAttributes())->toArray();
        $data['kind'] = $kind;
        $data['options'] = ['scopes' => ['global', 'client', 'site'], 'modes' => ['read_only', 'sync', 'managed'],
            'client_roles' => ['client_admin', 'site_admin', 'viewer', 'contact'],
            'sync_directions' => ['preview_only', 'nextcloud_to_nexum', 'nexum_to_nextcloud'],
            'provider_execution_enabled' => (bool) config('nextcloud_api.provider_execution_enabled')];

        return response()->json($data);
    }

